solutions.naive:
class Solution:
    def findDuplicate(self, nums: list[int]) -> int:
        for x in range(1, len(nums)):
            if sum(1 for y in nums if y == x) > 1:
                return x
        return -1

solutions.better:
class Solution:
    def findDuplicate(self, nums: list[int]) -> int:
        seen = set()
        for x in nums:
            if x in seen:
                return x
            seen.add(x)
        return -1

solutions.optimal:
class Solution:
    def findDuplicate(self, nums: list[int]) -> int:
        slow = nums[0]
        fast = nums[nums[0]]
        while slow != fast:
            slow = nums[slow]
            fast = nums[nums[fast]]
        slow = 0
        while slow != fast:
            slow = nums[slow]
            fast = nums[fast]
        return slow

